pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
    let arrival_scale = (total_items as f64 / 50.0).min(4.0).max(1.0);

    // Strictly penalize tiny dead gaps that cannot accommodate any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 180.0 * (10.0 - post_residual as f64);
    }

    // Favor nearly filling the selected bin, with a smooth nonlinear residual penalty.
    score += 2.8 * gap_ratio * gap_ratio * bin_capacity as f64;

    // Penalize leaving substantially more space than the stream's average.
    if post_residual as f64 > mean_residual {
        score += 1.4 * (post_residual as f64 - mean_residual);
    }

    // Encourage preserving room for the known next item when possible.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 75.0 * (next_item_size - post_residual) as f64;
    }

    // When this is the only fitting bin, avoid making a poor placement that forces another bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score += 55.0 * gap_ratio * gap_ratio;
    }

    // New bins are appropriate when pressure is low or current bins have poor residuals.
    if is_new_bin {
        score += 42.0 * pressure * arrival_scale;
        score += 0.55 * mean_residual;
        if next_item_size == 0 {
            score += 12.0;
        }
    } else {
        // Reward using an existing bin, especially when many bins are already open.
        score -= 34.0 * pressure;
        if post_residual == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Prefer a post-placement remainder that can accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 28.0 + 12.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 18.0 + 22.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Near the stream end, favor tighter residuals.
        score += 0.35 * post_residual as f64;
    }

    // Reward residuals near the mean, but retain a strong preference for exact lookahead fit.
    score += 0.30 * (post_residual as f64 - mean_residual).abs();

    // Very small remnants are usually difficult to reuse.
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 16.0 + 12.0 * (item_size.min(10) - post_residual) as f64;
    }

    // If this is the only fitting bin, a placement that blocks the next item is costly.
    if fitting_bins_count == 1 && next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Opening an empty bin is attractive mainly when existing options have poor residuals.
    if is_new_bin {
        score += 18.0;
        score += 0.10 * open_bins_count as f64;
        if progress > 0.85 {
            score -= 8.0;
        }
    }

    // Slightly discourage opening a new bin when many bins already remain open.
    if open_bins_count > 1 && fitting_bins_count > 1 {
        score += 0.03 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space below the smallest plausible future item is especially costly.
    let dead_space_threshold = 10.0;
    if (post_residual as f64) < dead_space_threshold {
        score += (dead_space_threshold - post_residual as f64) * 18.0;
    }

    // Tight fits are preferred; loose fits preserve capacity for larger arrivals.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 7.0;

    // Reward consuming capacity when many bins are open.
    let pressure = (open_bins_count as f64).sqrt();
    score -= pressure * (post_residual as f64) * 0.035;

    // Preserve the current bin for the known next item when possible.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            score -= 1.5;
        }
    }

    // If this is the only fitting bin, strongly prefer using it over opening another.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // A new bin should be opened only when existing placements are clearly worse.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 1.5;
    }

    // Mildly favor bins close to the mean residual, avoiding both very empty and extreme bins.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.025;

    // Near the end of the stream, favor immediate compaction over preserving space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strictly penalize tiny leftover gaps, since they are often unusable.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            score += 900.0 + (10.0 - gap) * 25.0;
        } else if gap < 20.0 {
            score += 250.0 + (20.0 - gap) * 8.0;
        } else {
            score += gap * 0.35;
        }
    }

    // Prefer an exact fit and strongly discourage splitting a large remaining gap.
    if gap == 0.0 {
        score -= 120.0;
    }

    // The lookahead item makes a small gap especially costly.
    if next_item_size > 0 {
        if gap < next_item_size as f64 {
            score += 180.0 + (next_item_size as f64 - gap) * 3.0;
        } else if gap < (next_item_size as f64 + 10.0) {
            score += 45.0;
        }
    }

    // Reward placements that keep residual space near the stream-wide target.
    if open_bins_count > 0 {
        let target = (mean_residual * 0.35).min(bin_capacity as f64 * 0.35);
        score += (gap - target).abs() * 1.5;
    }

    // Pressure toward consolidation increases as the stream advances.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let pressure = 1.0 + progress * 2.5;
    score -= (bin_residual as f64 - gap) * 0.05 * pressure;

    // If this is the only fitting bin, opening another bin is usually preferable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 110.0;
    }

    // Avoid opening a new bin while there is a reasonably close fit.
    if bin_residual == bin_capacity {
        score += 420.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 120.0;
        }
    }

    score
}

