pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Dead space that cannot accommodate the next known item is especially costly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Small residual gaps are generally undesirable, with stronger pressure
    // from many currently open bins.
    if post_residual > 0 && post_residual < 20 {
        let dead_weight = 1.0 + (open_bins_count as f64).sqrt() * 0.35;
        score += (20 - post_residual) as f64 * dead_weight;
    }

    // Reward tight fits and avoid wasting a newly opened bin.
    if bin_residual == bin_capacity {
        score += 18.0 + progress * 6.0;
    } else {
        score -= (item_size as f64 / bin_capacity.max(1) as f64) * 8.0;
    }

    // Prefer keeping residual capacity near the mean across open bins.
    score += ((post_residual as f64 - mean_residual) * 0.08).abs();

    // Pressure to consolidate items when many bins are already open.
    score += open_bins_count as f64 * 0.45;

    // If this is the only fitting bin, opening a new bin is relatively costly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let size = item_size as f64;
    let residual = bin_residual as f64;
    let next_size = next_item_size as f64;

    let dead_space_threshold = 10.0_f64.min(capacity * 0.20);
    let unusable_gap = post_residual as f64;
    let unusable_penalty = if unusable_gap < dead_space_threshold {
        (dead_space_threshold - unusable_gap) * 4.0
    } else {
        0.0
    };

    let fragmentation_penalty = if post_residual == 0 {
        0.0
    } else if (post_residual as u32) < next_size && next_size > 0.0 {
        3.0 * (next_size - post_residual as f64)
    } else {
        0.0
    };

    let fit_quality = if residual > 0.0 {
        size / residual
    } else {
        size / capacity
    };

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let pressure = open_bins_count as f64;
    let pressure_weight = 1.0 + 0.35 * pressure;
    let mean_gap_penalty = (mean_residual - post_residual as f64).max(0.0) * 0.20;

    score += unusable_penalty * pressure_weight;
    score += fragmentation_penalty * (1.0 + 0.25 * pressure);
    score += mean_gap_penalty;

    score -= 0.15 * fit_quality;

    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * pressure;
        score -= 0.5 * progress;
    }

    if next_size > 0.0 && post_residual as f64 >= next_size {
        score -= 2.0;
    }

    score
}
